action.script:
#!/bin/bash
set -euo pipefail

# Extract certificates from secrets with type kubernetes.io/tls
kubectl get secrets --all-namespaces -o json | jq -r '
  .items[] |
  select(.type == "kubernetes.io/tls") |
  {
    namespace: .metadata.namespace,
    name: .metadata.name,
    cert: .data."tls.crt"
  } |
  @base64d'
